insert into public.posts (id, legacy_id, community_slug, title, type, content, author_username, upvotes, solved, tags) values ('cc064d48-486f-0643-b530-41fe83892499', '1', 'french', 'How do I stop mixing up etre and avoir in the passe compose?', 'question', 'I understand the basic rule, but when I write quickly I keep choosing the wrong auxiliary. What clues do you use before picking etre or avoir?', 'lyuk', 34, true, array['passe compose','auxiliaries','grammar']::text[]);
insert into public.comments (id, legacy_id, post_id, author_username, content, upvotes, accepted) values ('392491e2-882c-3d26-1e81-52c3047a1ac4', '1', 'cc064d48-486f-0643-b530-41fe83892499', 'anna', 'Start by checking whether the verb is reflexive. If it is, use etre almost every time in basic learner sentences.', 18, true);
insert into public.comment_replies (id, legacy_id, comment_id, author_username, content) values ('9af3eb39-44e6-d284-498e-2f1001313416', '101', '392491e2-882c-3d26-1e81-52c3047a1ac4', 'lyuk', 'That shortcut helps. I was treating reflexive verbs like a separate topic.');
insert into public.comment_replies (id, legacy_id, comment_id, author_username, content) values ('03b31015-3a12-59b0-1d72-b6b98faa0072', '102', '392491e2-882c-3d26-1e81-52c3047a1ac4', 'marie', 'It also helps to say the whole phrase out loud because reflexive verbs sound incomplete without the pronoun.');
insert into public.comments (id, legacy_id, post_id, author_username, content, upvotes, accepted) values ('82ea8031-f90a-5b40-92f4-eaff696015c3', '2', 'cc064d48-486f-0643-b530-41fe83892499', 'lucas', 'Memorize the movement verbs as a tiny story: arrive, go in, go out, go up, go down, return, leave, stay, fall, die, be born.', 12, false);
insert into public.comment_replies (id, legacy_id, comment_id, author_username, content) values ('8e68003f-8eff-f0e1-2234-317c92540739', '201', '82ea8031-f90a-5b40-92f4-eaff696015c3', 'sarah', 'The story method finally made the list stick for me.');
insert into public.comments (id, legacy_id, post_id, author_username, content, upvotes, accepted) values ('811b6ed2-0fd3-9115-f9fa-6e544eb88ac5', '3', 'cc064d48-486f-0643-b530-41fe83892499', 'pablo', 'When the verb takes a direct object, it usually switches to avoir. Compare ''je suis sorti'' and ''j''ai sorti le livre''.', 16, false);
insert into public.comment_replies (id, legacy_id, comment_id, author_username, content) values ('760d0de9-790c-1032-85d0-84c1d1a64660', '301', '811b6ed2-0fd3-9115-f9fa-6e544eb88ac5', 'lyuk', 'That example explains why I was confused by sortir.');
insert into public.comment_replies (id, legacy_id, comment_id, author_username, content) values ('cb1f39c0-ca8f-e2de-5f70-b4bd72d3fc04', '302', '811b6ed2-0fd3-9115-f9fa-6e544eb88ac5', 'anna', 'Yes, those verbs are the tricky edge cases.');
insert into public.comments (id, legacy_id, post_id, author_username, content, upvotes, accepted) values ('33436705-89fa-d422-d388-eae58c016974', '4', 'cc064d48-486f-0643-b530-41fe83892499', 'camille', 'Make two columns in your notes: verbs that describe a change of location, and verbs that act on an object.', 9, false);
insert into public.comments (id, legacy_id, post_id, author_username, content, upvotes, accepted) values ('adc2963f-2057-ed2a-f19e-d09d164cfa97', '5', 'cc064d48-486f-0643-b530-41fe83892499', 'noah', 'I used color coding for a week. Blue for etre, gray for avoir. It made mistakes obvious when I reviewed.', 7, false);
insert into public.comment_replies (id, legacy_id, comment_id, author_username, content) values ('3480d887-cf05-7977-49b6-37dfcdd9afcf', '501', 'adc2963f-2057-ed2a-f19e-d09d164cfa97', 'lucas', 'That is simple enough to try tonight.');
insert into public.comments (id, legacy_id, post_id, author_username, content, upvotes, accepted) values ('848416bf-a45c-3505-7b10-3828cb1fe736', '6', 'cc064d48-486f-0643-b530-41fe83892499', 'elise', 'Do not forget agreement with etre. The auxiliary choice is only half of the pattern.', 11, false);
insert into public.posts (id, legacy_id, community_slug, title, type, content, author_username, upvotes, solved, tags) values ('12d57bca-a4c4-2912-174d-3b040612d8bf', '2', 'french', 'Best way to practice nasal vowels without annoying my neighbors?', 'discussion', 'I want to drill un, on, and an, but repeating them loudly feels awkward. What low-volume exercises actually work?', 'sarah', 21, false, array['pronunciation','nasal vowels','practice']::text[]);
insert into public.comments (id, legacy_id, post_id, author_username, content, upvotes, accepted) values ('e8d3a327-a790-1b0d-fc94-cf05665f23d3', '1', '12d57bca-a4c4-2912-174d-3b040612d8bf', 'marie', 'Hum the vowel first, then open into the word quietly. It trains the resonance without needing volume.', 10, false);
insert into public.comment_replies (id, legacy_id, comment_id, author_username, content) values ('91355e84-b1e3-4093-13f5-3acc258fe22c', '101', 'e8d3a327-a790-1b0d-fc94-cf05665f23d3', 'sarah', 'This feels less awkward already.');
insert into public.comments (id, legacy_id, post_id, author_username, content, upvotes, accepted) values ('cc4aeaf6-84fc-e6e4-5142-819f646aaa53', '2', '12d57bca-a4c4-2912-174d-3b040612d8bf', 'anna', 'Record short pairs like beau and bon. Listening back catches more than practicing louder.', 8, false);
insert into public.comments (id, legacy_id, post_id, author_username, content, upvotes, accepted) values ('ac909d1a-537d-005f-fede-7c3c871be5bd', '3', '12d57bca-a4c4-2912-174d-3b040612d8bf', 'pablo', 'Try shadowing news clips at whisper volume. The rhythm matters as much as the single sounds.', 6, false);
insert into public.comment_replies (id, legacy_id, comment_id, author_username, content) values ('e80b33b7-5900-4b2b-f017-0b5f1915d644', '301', 'ac909d1a-537d-005f-fede-7c3c871be5bd', 'lucas', 'Whisper shadowing made my intonation better too.');
insert into public.posts (id, legacy_id, community_slug, title, type, content, author_username, upvotes, solved, tags) values ('a79af164-9604-b119-3674-85a4028852a1', '1', 'chemistry', 'Why does NaCl dissolve in water but not in oil?', 'question', 'I know water is polar, but I do not understand what is happening at the ion level when salt dissolves.', 'lucas', 42, true, array['solutions','polarity','ionic compounds']::text[]);
insert into public.comments (id, legacy_id, post_id, author_username, content, upvotes, accepted) values ('1f943b4f-528b-dcb2-61ca-12757375c2df', '1', 'a79af164-9604-b119-3674-85a4028852a1', 'sarah', 'Water molecules surround each ion. The oxygen side points toward sodium, while the hydrogen side points toward chloride.', 21, true);
insert into public.comment_replies (id, legacy_id, comment_id, author_username, content) values ('5511f028-b34f-e153-2ec4-26789fa2b9b9', '101', '1f943b4f-528b-dcb2-61ca-12757375c2df', 'lucas', 'So the water is not breaking the atoms, just separating ions?');
insert into public.comment_replies (id, legacy_id, comment_id, author_username, content) values ('1f540ca6-bf03-c0c4-a04e-6f903936b026', '102', '1f943b4f-528b-dcb2-61ca-12757375c2df', 'sarah', 'Exactly. The ions already exist in the crystal lattice.');
insert into public.comments (id, legacy_id, post_id, author_username, content, upvotes, accepted) values ('42f5f240-a71f-b186-420b-060ee4bb0fb5', '2', 'a79af164-9604-b119-3674-85a4028852a1', 'maya', 'Oil molecules are mostly nonpolar, so they do not stabilize separated charges well.', 17, false);
insert into public.comments (id, legacy_id, post_id, author_username, content, upvotes, accepted) values ('2c3a45ae-0be3-7947-961e-0ba658519c2a', '3', 'a79af164-9604-b119-3674-85a4028852a1', 'pablo', 'Think of it as a tradeoff: water pays the energy cost of pulling ions apart by forming strong ion-dipole attractions.', 15, false);
insert into public.comment_replies (id, legacy_id, comment_id, author_username, content) values ('d367e2bf-095a-ec39-7e7c-7dcb009fb3b1', '301', '2c3a45ae-0be3-7947-961e-0ba658519c2a', 'noah', 'This energy explanation makes the rule feel less random.');
insert into public.comments (id, legacy_id, post_id, author_username, content, upvotes, accepted) values ('416a453a-9027-a2e0-536e-96fd0ddac585', '4', 'a79af164-9604-b119-3674-85a4028852a1', 'anna', 'A diagram of hydration shells is useful here. Each ion gets surrounded by water in an organized way.', 8, false);
insert into public.comments (id, legacy_id, post_id, author_username, content, upvotes, accepted) values ('c5e624fd-88c9-ab8c-566b-69e588005b0f', '5', 'a79af164-9604-b119-3674-85a4028852a1', 'diego', 'Temperature and agitation can change speed, but they do not make oil good at dissolving salt.', 5, false);
insert into public.comment_replies (id, legacy_id, comment_id, author_username, content) values ('630ae042-2b74-806c-c44d-5fe5db487f46', '501', 'c5e624fd-88c9-ab8c-566b-69e588005b0f', 'lucas', 'That answers my cooking experiment question too.');
insert into public.comments (id, legacy_id, post_id, author_username, content, upvotes, accepted) values ('3fffdb76-14d0-a833-567b-cc9ca8926202', '6', 'a79af164-9604-b119-3674-85a4028852a1', 'camille', 'The phrase ''like dissolves like'' is oversimplified, but polarity is the key idea for this example.', 11, false);
insert into public.comments (id, legacy_id, post_id, author_username, content, upvotes, accepted) values ('a9e87074-df8c-a670-c3b3-01bfd6d33d01', '7', 'a79af164-9604-b119-3674-85a4028852a1', 'elise', 'If you compare salt with sugar, sugar dissolves differently because it stays molecular instead of separating into ions.', 9, false);
insert into public.comment_replies (id, legacy_id, comment_id, author_username, content) values ('e7ca5ff1-db67-067c-183d-ee8695b8ca75', '701', 'a9e87074-df8c-a670-c3b3-01bfd6d33d01', 'maya', 'Nice contrast. Both interact with water, but by different attractions.');
insert into public.comments (id, legacy_id, post_id, author_username, content, upvotes, accepted) values ('295e744c-e4b8-214f-f647-1cc5c813e9ca', '8', 'a79af164-9604-b119-3674-85a4028852a1', 'omar', 'Your textbook may call the attraction ion-dipole interaction. That is the term to look up.', 6, false);
insert into public.posts (id, legacy_id, community_slug, title, type, content, author_username, upvotes, solved, tags) values ('025aa8aa-4ae4-7f23-8216-bb142be402a3', '2', 'chemistry', 'How do you balance redox reactions without losing track?', 'discussion', 'Half-reactions make sense when someone else does them, but my own work gets messy fast.', 'anna', 28, false, array['redox','balancing','study tips']::text[]);
insert into public.comments (id, legacy_id, post_id, author_username, content, upvotes, accepted) values ('472385b8-2dc4-ce2f-40e1-7f0612ff73b8', '1', '025aa8aa-4ae4-7f23-8216-bb142be402a3', 'noah', 'Write oxidation numbers above every changing element before touching coefficients.', 12, false);
insert into public.comments (id, legacy_id, post_id, author_username, content, upvotes, accepted) values ('eefcb4ba-ccf9-9d34-da33-f800ef7edfe0', '2', '025aa8aa-4ae4-7f23-8216-bb142be402a3', 'maya', 'Balance atoms other than oxygen and hydrogen first, then oxygen with water, then hydrogen with H+.', 15, false);
insert into public.comment_replies (id, legacy_id, comment_id, author_username, content) values ('e5fd6b81-7423-5953-8131-5aa91da6a9da', '201', 'eefcb4ba-ccf9-9d34-da33-f800ef7edfe0', 'anna', 'I was adding water too early. That may be my issue.');
insert into public.comments (id, legacy_id, post_id, author_username, content, upvotes, accepted) values ('48004437-526d-c00d-6cd8-8bff15a2753b', '3', '025aa8aa-4ae4-7f23-8216-bb142be402a3', 'diego', 'For basic solution, do the acid method first, then neutralize H+ with OH- at the end.', 14, false);
insert into public.comment_replies (id, legacy_id, comment_id, author_username, content) values ('83eea85e-31d8-743b-7f4e-3e9095b03214', '301', '48004437-526d-c00d-6cd8-8bff15a2753b', 'sarah', 'This is the cleanest workflow for exams.');
insert into public.comment_replies (id, legacy_id, comment_id, author_username, content) values ('dbbc7dfc-b662-7bff-cda1-10bb7e307754', '302', '48004437-526d-c00d-6cd8-8bff15a2753b', 'lucas', 'And cancel water after adding OH- to both sides.');
insert into public.comments (id, legacy_id, post_id, author_username, content, upvotes, accepted) values ('a3b28e04-7f37-ff91-5d66-b19d609d3a36', '4', '025aa8aa-4ae4-7f23-8216-bb142be402a3', 'pablo', 'Keep charge balance as a separate line in your notes. It catches mistakes immediately.', 8, false);
insert into public.comments (id, legacy_id, post_id, author_username, content, upvotes, accepted) values ('70f303c8-e6df-b4a7-518f-1977cef52b47', '5', '025aa8aa-4ae4-7f23-8216-bb142be402a3', 'camille', 'Use arrows and boxes for electrons. Messy redox work is usually messy bookkeeping.', 7, false);
insert into public.posts (id, legacy_id, community_slug, title, type, content, author_username, upvotes, solved, tags) values ('39cb9f6c-8f6b-0dd3-5ba4-143c5b4b31cd', '1', 'javascript', 'When should I use useMemo instead of just calculating in render?', 'question', 'I see useMemo everywhere in examples, but I am not sure when it actually improves a React component.', 'pablo', 39, true, array['react','performance','usememo']::text[]);
insert into public.comments (id, legacy_id, post_id, author_username, content, upvotes, accepted) values ('1b512849-4af2-35cb-a6ad-0a5d6302242f', '1', '39cb9f6c-8f6b-0dd3-5ba4-143c5b4b31cd', 'lucas', 'Use it when the calculation is expensive or when stable object identity prevents unnecessary child renders.', 20, true);
insert into public.comment_replies (id, legacy_id, comment_id, author_username, content) values ('5ce49564-0699-ef27-ca19-5dc2403af144', '101', '1b512849-4af2-35cb-a6ad-0a5d6302242f', 'pablo', 'Stable identity is the part I had missed.');
insert into public.comments (id, legacy_id, post_id, author_username, content, upvotes, accepted) values ('bdb5b7f3-fcce-9f3c-6731-57e325eb57d3', '2', '39cb9f6c-8f6b-0dd3-5ba4-143c5b4b31cd', 'maya', 'Do not add it for tiny calculations. The dependency array adds its own maintenance cost.', 16, false);
insert into public.comments (id, legacy_id, post_id, author_username, content, upvotes, accepted) values ('a4d9131c-434b-5718-56a1-432640211b58', '3', '39cb9f6c-8f6b-0dd3-5ba4-143c5b4b31cd', 'noah', 'Profile first if you are unsure. React DevTools Profiler will show whether render time is actually a problem.', 13, false);
insert into public.comment_replies (id, legacy_id, comment_id, author_username, content) values ('fb10f618-4dea-0c02-6510-e2b9d6cd72dd', '301', 'a4d9131c-434b-5718-56a1-432640211b58', 'anna', 'This saved me from optimizing the wrong component last week.');
insert into public.comment_replies (id, legacy_id, comment_id, author_username, content) values ('6e5bf261-31d1-cb2d-bf55-52a264e33c26', '302', 'a4d9131c-434b-5718-56a1-432640211b58', 'pablo', 'Good point. I was guessing from code shape.');
insert into public.comments (id, legacy_id, post_id, author_username, content, upvotes, accepted) values ('b081197b-5108-b7d5-ec82-9c0005754912', '4', '39cb9f6c-8f6b-0dd3-5ba4-143c5b4b31cd', 'elise', 'If the memoized value is passed to a memoized child, it matters more. Otherwise it may do nothing visible.', 10, false);
insert into public.posts (id, legacy_id, community_slug, title, type, content, author_username, upvotes, solved, tags) values ('f695bb83-5954-4a13-af23-b0be318a46dc', '2', 'javascript', 'Small project ideas for practicing async JavaScript?', 'discussion', 'I know promises and async/await in isolation, but I want a project where the patterns show up naturally.', 'sarah', 31, false, array['async','projects','javascript']::text[]);
insert into public.comments (id, legacy_id, post_id, author_username, content, upvotes, accepted) values ('58816118-fd50-df2c-4fd6-c8ad113eb21d', '1', 'f695bb83-5954-4a13-af23-b0be318a46dc', 'lyuk', 'Build a weather dashboard with loading, error, and retry states. It is simple but covers the basics.', 14, false);
insert into public.comment_replies (id, legacy_id, comment_id, author_username, content) values ('d76d31f7-1550-6f0c-a0fe-a0722cd7b092', '101', '58816118-fd50-df2c-4fd6-c8ad113eb21d', 'sarah', 'Retry states are a good idea. I usually skip them.');
insert into public.comments (id, legacy_id, post_id, author_username, content, upvotes, accepted) values ('cea71c27-0b24-468b-c798-cd07d5622b72', '2', 'f695bb83-5954-4a13-af23-b0be318a46dc', 'anna', 'A recipe search app is great because you can debounce input and cancel stale requests.', 17, false);
insert into public.comment_replies (id, legacy_id, comment_id, author_username, content) values ('8a75c1ec-e71d-853a-7ab3-4db0c154964a', '201', 'cea71c27-0b24-468b-c798-cd07d5622b72', 'lucas', 'AbortController fits perfectly there.');
insert into public.comments (id, legacy_id, post_id, author_username, content, upvotes, accepted) values ('4ba1752b-21ec-9d1f-3c8c-5bd5a1d4fe1c', '3', 'f695bb83-5954-4a13-af23-b0be318a46dc', 'noah', 'Try a file upload mock that shows progress. Even fake progress teaches state sequencing.', 8, false);
insert into public.comments (id, legacy_id, post_id, author_username, content, upvotes, accepted) values ('85215213-6d57-94fb-eb9d-f49dbf592ca3', '4', 'f695bb83-5954-4a13-af23-b0be318a46dc', 'maya', 'A GitHub profile lookup lets you practice parallel requests for repos, followers, and profile data.', 13, false);
insert into public.comment_replies (id, legacy_id, comment_id, author_username, content) values ('a5a7e36c-98aa-579c-ba39-8499aff5b526', '401', '85215213-6d57-94fb-eb9d-f49dbf592ca3', 'pablo', 'Promise.all feels much clearer in that kind of project.');
insert into public.comments (id, legacy_id, post_id, author_username, content, upvotes, accepted) values ('7313da20-547a-f493-f688-16811cecb202', '5', 'f695bb83-5954-4a13-af23-b0be318a46dc', 'diego', 'Make a tiny chat simulator with delayed responses. It reveals race conditions quickly.', 9, false);
insert into public.comments (id, legacy_id, post_id, author_username, content, upvotes, accepted) values ('90551422-d95a-7cb1-3644-15f1d2537283', '6', 'f695bb83-5954-4a13-af23-b0be318a46dc', 'camille', 'A quiz app with server-saved answers gives you optimistic updates and rollback practice.', 11, false);
insert into public.comments (id, legacy_id, post_id, author_username, content, upvotes, accepted) values ('03a32904-10e6-119c-c806-7ea2eef917c2', '7', 'f695bb83-5954-4a13-af23-b0be318a46dc', 'omar', 'Whatever you build, add artificial delays so the loading states are visible while developing.', 10, false);
insert into public.comment_replies (id, legacy_id, comment_id, author_username, content) values ('bb1ab41e-ffdd-e04a-f08b-e959b68ab2fd', '701', '03a32904-10e6-119c-c806-7ea2eef917c2', 'sarah', 'That makes sense. Fast local requests hide the real behavior.');
insert into public.posts (id, legacy_id, community_slug, title, type, content, author_username, upvotes, solved, tags) values ('0ebdc4e6-f5e6-c86e-f000-65b065a10a21', '1', 'german', 'How do I know when a preposition takes dative or accusative?', 'question', 'Two-way prepositions are confusing me. Is there a reliable way to decide which case to use?', 'anna', 27, true, array['cases','prepositions','grammar']::text[]);
insert into public.comments (id, legacy_id, post_id, author_username, content, upvotes, accepted) values ('bf012fbe-3170-e9e6-60f0-9867a5f8dfad', '1', '0ebdc4e6-f5e6-c86e-f000-65b065a10a21', 'elise', 'Use accusative for movement toward a destination, and dative for location at rest.', 19, true);
insert into public.comment_replies (id, legacy_id, comment_id, author_username, content) values ('59bcbcd0-f189-52ef-5f15-631da8b4f1fe', '101', 'bf012fbe-3170-e9e6-60f0-9867a5f8dfad', 'anna', 'That is much simpler than my chart.');
insert into public.comments (id, legacy_id, post_id, author_username, content, upvotes, accepted) values ('085443c9-1abf-5708-a9e0-fe352246eaf1', '2', '0ebdc4e6-f5e6-c86e-f000-65b065a10a21', 'noah', 'Ask ''where to?'' for accusative and ''where?'' for dative. The German questions are wohin and wo.', 15, false);
insert into public.comments (id, legacy_id, post_id, author_username, content, upvotes, accepted) values ('50372729-0771-74bd-7919-db1fc3c3daad', '3', '0ebdc4e6-f5e6-c86e-f000-65b065a10a21', 'marie', 'Practice with pairs: ich gehe in die Schule, ich bin in der Schule.', 12, false);
insert into public.comment_replies (id, legacy_id, comment_id, author_username, content) values ('020c3c0e-89ec-3197-68df-573631533ec8', '301', '50372729-0771-74bd-7919-db1fc3c3daad', 'lyuk', 'Pairs make the contrast obvious.');
insert into public.comment_replies (id, legacy_id, comment_id, author_username, content) values ('c3913952-1edf-bc60-79c2-5fb3fc1b1fd8', '302', '50372729-0771-74bd-7919-db1fc3c3daad', 'elise', 'Exactly. Isolated sentences are harder to remember.');
insert into public.posts (id, legacy_id, community_slug, title, type, content, author_username, upvotes, solved, tags) values ('c214dcba-6cb8-9f0e-0df9-365c1a4a6011', '2', 'german', 'Favorite routines for building German vocabulary?', 'discussion', 'I can memorize lists for a test, but I forget them two weeks later. What routines make vocabulary stick?', 'lucas', 24, false, array['vocabulary','study routine','memory']::text[]);
insert into public.comments (id, legacy_id, post_id, author_username, content, upvotes, accepted) values ('e25e9c2f-9b19-75e1-bbc8-5e31c745053e', '1', 'c214dcba-6cb8-9f0e-0df9-365c1a4a6011', 'sarah', 'Add whole example sentences to your flashcards, not single words. Gender and usage stick together.', 13, false);
insert into public.comments (id, legacy_id, post_id, author_username, content, upvotes, accepted) values ('0dff499d-7955-a5ab-e9ea-637398678fb3', '2', 'c214dcba-6cb8-9f0e-0df9-365c1a4a6011', 'pablo', 'I keep a five-minute evening review and a longer Sunday cleanup. Small daily contact beats cramming.', 11, false);
insert into public.comment_replies (id, legacy_id, comment_id, author_username, content) values ('fe82c72d-ca76-f57b-11b5-1273e1b0032e', '201', '0dff499d-7955-a5ab-e9ea-637398678fb3', 'lucas', 'A Sunday cleanup sounds realistic.');
insert into public.comments (id, legacy_id, post_id, author_username, content, upvotes, accepted) values ('09bb16ac-126c-bd6d-c667-874e75130212', '3', 'c214dcba-6cb8-9f0e-0df9-365c1a4a6011', 'elise', 'Group nouns by article color. Blue for der, red for die, green for das worked for me.', 9, false);
insert into public.comments (id, legacy_id, post_id, author_username, content, upvotes, accepted) values ('7d3b5509-ecfa-8a13-eae1-dae6b8c3d7f2', '4', 'c214dcba-6cb8-9f0e-0df9-365c1a4a6011', 'lyuk', 'Read short graded texts and mine only the words you see twice. That filters out noise.', 14, false);
insert into public.comment_replies (id, legacy_id, comment_id, author_username, content) values ('65395d5f-edfc-1f17-1376-ff9f12b722d4', '401', '7d3b5509-ecfa-8a13-eae1-dae6b8c3d7f2', 'anna', 'This is underrated. Frequency keeps the deck manageable.');
insert into public.comments (id, legacy_id, post_id, author_username, content, upvotes, accepted) values ('ff558433-1c55-4040-052d-a4bb0bc91b99', '5', 'c214dcba-6cb8-9f0e-0df9-365c1a4a6011', 'camille', 'Say new verbs with one object or preposition. Learning warten with auf saves trouble later.', 8, false);
insert into public.comments (id, legacy_id, post_id, author_username, content, upvotes, accepted) values ('4dfe903b-ed32-47bb-4517-559d23c18037', '6', 'c214dcba-6cb8-9f0e-0df9-365c1a4a6011', 'noah', 'Make tiny voice notes with three new words and play them during a walk.', 6, false);
insert into public.posts (id, legacy_id, community_slug, title, type, content, author_username, upvotes, solved, tags) values ('d27e4098-d665-1a9a-258d-9c2555b5f847', '1', 'quantum_physics', 'Is superposition just not knowing the answer yet?', 'question', 'Some explanations make superposition sound like ignorance. Others make it sound physically real. Which is closer?', 'maya', 47, true, array['superposition','measurement','concepts']::text[]);
insert into public.comments (id, legacy_id, post_id, author_username, content, upvotes, accepted) values ('c778cabd-d96f-9898-46f6-140317ffc745', '1', 'd27e4098-d665-1a9a-258d-9c2555b5f847', 'omar', 'It is not the same as classical ignorance. A superposed state can produce interference, which a simple hidden answer would not explain.', 24, true);
insert into public.comment_replies (id, legacy_id, comment_id, author_username, content) values ('d4af775a-0f6c-f8fd-97c3-883da7cac800', '101', 'c778cabd-d96f-9898-46f6-140317ffc745', 'maya', 'Interference is the missing piece in most beginner explanations.');
insert into public.comments (id, legacy_id, post_id, author_username, content, upvotes, accepted) values ('26903f9a-e316-0ed5-32ff-9eb7c0fef6e9', '2', 'd27e4098-d665-1a9a-258d-9c2555b5f847', 'lucas', 'The math represents amplitudes, not ordinary probabilities. Probabilities come after squaring amplitudes.', 18, false);
insert into public.comments (id, legacy_id, post_id, author_username, content, upvotes, accepted) values ('dd2ac2f8-6983-8c69-4b8c-2b25afdc6af9', '3', 'd27e4098-d665-1a9a-258d-9c2555b5f847', 'noah', 'Different interpretations describe what is real differently, but they agree on the predictions.', 14, false);
insert into public.comment_replies (id, legacy_id, comment_id, author_username, content) values ('e9e13ec0-3825-07d1-7f16-f2c28225bc4e', '301', 'dd2ac2f8-6983-8c69-4b8c-2b25afdc6af9', 'sarah', 'That helps separate physics from interpretation debates.');
insert into public.comments (id, legacy_id, post_id, author_username, content, upvotes, accepted) values ('a88f0f7c-f136-24cb-c8f5-a8d21bcf98bf', '4', 'd27e4098-d665-1a9a-258d-9c2555b5f847', 'anna', 'The double-slit experiment is the cleanest example to study next.', 12, false);
insert into public.comments (id, legacy_id, post_id, author_username, content, upvotes, accepted) values ('4a582993-277d-02fb-5edf-1ab4cca67590', '5', 'd27e4098-d665-1a9a-258d-9c2555b5f847', 'diego', 'Be careful with the phrase ''particle is in two places''. It is a useful image but not the full formal statement.', 11, false);
insert into public.comment_replies (id, legacy_id, comment_id, author_username, content) values ('8a0daf92-0df9-04f8-4372-82c420162ec0', '501', '4a582993-277d-02fb-5edf-1ab4cca67590', 'maya', 'Good warning. The image was making me overconfident.');
insert into public.comment_replies (id, legacy_id, comment_id, author_username, content) values ('669f93ac-55df-b394-23b4-0c7f5ac5b1d1', '502', '4a582993-277d-02fb-5edf-1ab4cca67590', 'omar', 'That happens a lot with popular explanations.');
insert into public.posts (id, legacy_id, community_slug, title, type, content, author_username, upvotes, solved, tags) values ('2ee13030-100f-0e4e-6168-f956d6d5b538', '2', 'quantum_physics', 'Beginner-friendly path before tackling Griffiths?', 'discussion', 'I want to read Griffiths eventually, but my linear algebra is rusty. What should I review first?', 'pablo', 33, false, array['resources','linear algebra','study plan']::text[]);
insert into public.comments (id, legacy_id, post_id, author_username, content, upvotes, accepted) values ('9490e97a-0bd6-fd4d-7528-75321539bc95', '1', '2ee13030-100f-0e4e-6168-f956d6d5b538', 'omar', 'Review complex numbers, eigenvectors, inner products, and change of basis. Those show up constantly.', 20, false);
insert into public.comment_replies (id, legacy_id, comment_id, author_username, content) values ('943c180a-6fcb-8b87-d66a-fb8cd85ac8ac', '101', '9490e97a-0bd6-fd4d-7528-75321539bc95', 'pablo', 'That gives me a concrete checklist.');
insert into public.comments (id, legacy_id, post_id, author_username, content, upvotes, accepted) values ('a4cde6c1-5822-c925-da8a-32bb7a51450c', '2', '2ee13030-100f-0e4e-6168-f956d6d5b538', 'maya', 'Do not skip differential equations. Even basic separable and second-order equations help a lot.', 16, false);
insert into public.comments (id, legacy_id, post_id, author_username, content, upvotes, accepted) values ('4895a993-81e7-3442-d12e-e7bd68c78291', '3', '2ee13030-100f-0e4e-6168-f956d6d5b538', 'lucas', 'MIT OCW has good lectures for the math refresh. Pair that with problem solving, not just watching.', 13, false);
insert into public.comment_replies (id, legacy_id, comment_id, author_username, content) values ('64697aa5-f166-0aef-3df4-91eca448b6b6', '301', '4895a993-81e7-3442-d12e-e7bd68c78291', 'anna', 'The problem sets are where the ideas actually settle.');
insert into public.comments (id, legacy_id, post_id, author_username, content, upvotes, accepted) values ('2a0479f5-608c-d16b-bdd8-7b3687eb1d3b', '4', '2ee13030-100f-0e4e-6168-f956d6d5b538', 'sarah', 'Try Townsend before Griffiths if you want a gentler spin-first route.', 10, false);
insert into public.comments (id, legacy_id, post_id, author_username, content, upvotes, accepted) values ('f659392b-4952-bdaa-4f9c-58276214b326', '5', '2ee13030-100f-0e4e-6168-f956d6d5b538', 'diego', 'Learn bra-ket notation early. It makes later chapters feel much less cryptic.', 12, false);
insert into public.comment_replies (id, legacy_id, comment_id, author_username, content) values ('c3509762-f505-c499-fd31-6317226ae9d0', '501', 'f659392b-4952-bdaa-4f9c-58276214b326', 'pablo', 'I have seen it, but never used it in calculations.');
insert into public.comment_replies (id, legacy_id, comment_id, author_username, content) values ('143a6ada-0499-a7f9-fd1f-3efacde92547', '502', 'f659392b-4952-bdaa-4f9c-58276214b326', 'diego', 'A few two-state-system exercises are enough to get started.');
insert into public.comments (id, legacy_id, post_id, author_username, content, upvotes, accepted) values ('84acb55f-b8df-c235-d42f-430727478a83', '6', '2ee13030-100f-0e4e-6168-f956d6d5b538', 'noah', 'Set a weekly problem target. Quantum texts are dense if you only read them passively.', 9, false);
insert into public.comments (id, legacy_id, post_id, author_username, content, upvotes, accepted) values ('d79c0716-3b1e-b943-c6c1-6097f1b27f02', '7', '2ee13030-100f-0e4e-6168-f956d6d5b538', 'camille', 'For intuition, supplement with simulations of wave packets and wells.', 7, false);
insert into public.comments (id, legacy_id, post_id, author_username, content, upvotes, accepted) values ('d9b3c036-460c-f6c9-6bc9-db445440f80b', '8', '2ee13030-100f-0e4e-6168-f956d6d5b538', 'elise', 'Keep a separate sheet of common operators and what they mean physically.', 8, false);
insert into public.comment_replies (id, legacy_id, comment_id, author_username, content) values ('f8d7a88c-aa58-ed71-e01e-e801229bb3cd', '801', 'd9b3c036-460c-f6c9-6bc9-db445440f80b', 'maya', 'That sheet becomes gold before exams.');
insert into public.posts (id, legacy_id, community_slug, title, type, content, author_username, upvotes, solved, tags) values ('9b276411-9a62-7fe0-6027-e9a41e596aa9', '1', 'algebra', 'Why does completing the square work?', 'question', 'I can follow the steps, but I do not understand why adding half the coefficient squared creates a square.', 'camille', 30, true, array['quadratics','completing the square','concepts']::text[]);
insert into public.comments (id, legacy_id, post_id, author_username, content, upvotes, accepted) values ('d0b73559-9657-dc9e-541e-b0abe179cb50', '1', '9b276411-9a62-7fe0-6027-e9a41e596aa9', 'anna', 'Because (x + a)^2 expands to x^2 + 2ax + a^2. If your middle term is bx, then a must be b/2.', 18, true);
insert into public.comment_replies (id, legacy_id, comment_id, author_username, content) values ('50ec0fc4-887a-0132-c27d-6332b45de5df', '101', 'd0b73559-9657-dc9e-541e-b0abe179cb50', 'camille', 'Seeing it from the expansion makes the step feel less magical.');
insert into public.comments (id, legacy_id, post_id, author_username, content, upvotes, accepted) values ('3a013f8b-4c81-03d1-93c9-4e8dd4867ee8', '2', '9b276411-9a62-7fe0-6027-e9a41e596aa9', 'noah', 'Draw a square with side x plus two rectangles. The missing corner has area (b/2)^2.', 14, false);
insert into public.comments (id, legacy_id, post_id, author_username, content, upvotes, accepted) values ('428a71a6-41ee-7f07-f192-fa0eb1236fe7', '3', '9b276411-9a62-7fe0-6027-e9a41e596aa9', 'lucas', 'It also moves the parabola into vertex form, which reveals the turning point.', 12, false);
insert into public.comment_replies (id, legacy_id, comment_id, author_username, content) values ('76abc7d3-8fab-0747-fdcb-1a3b268d3278', '301', '428a71a6-41ee-7f07-f192-fa0eb1236fe7', 'pablo', 'That connection helped me graph quadratics faster.');
insert into public.comments (id, legacy_id, post_id, author_username, content, upvotes, accepted) values ('88105096-6ac9-c375-36fd-6ab8bf633789', '4', '9b276411-9a62-7fe0-6027-e9a41e596aa9', 'sarah', 'Try it with x^2 + 6x. Half of 6 is 3, and x^2 + 6x + 9 is (x + 3)^2.', 10, false);
insert into public.posts (id, legacy_id, community_slug, title, type, content, author_username, upvotes, solved, tags) values ('ed602080-d33e-7648-3f5b-8fe785c91211', '2', 'algebra', 'How many practice problems are enough before a test?', 'discussion', 'I keep doing the same kind of algebra problem until I feel comfortable, then the test changes the wording and I freeze.', 'lyuk', 19, false, array['study habits','tests','practice']::text[]);
insert into public.comments (id, legacy_id, post_id, author_username, content, upvotes, accepted) values ('37d634f0-7f07-4500-85b8-ee0816775152', '1', 'ed602080-d33e-7648-3f5b-8fe785c91211', 'pablo', 'Instead of counting problems, count problem types. You want mixed practice across factoring, graphing, simplifying, and word problems.', 11, false);
insert into public.comment_replies (id, legacy_id, comment_id, author_username, content) values ('f3c1f631-7255-a453-1829-37bacc6d1cef', '101', '37d634f0-7f07-4500-85b8-ee0816775152', 'lyuk', 'Mixed practice is probably what I am missing.');
insert into public.comments (id, legacy_id, post_id, author_username, content, upvotes, accepted) values ('7473d43b-61ba-7f84-2928-a2080050afe3', '2', 'ed602080-d33e-7648-3f5b-8fe785c91211', 'anna', 'After every five problems, write one sentence explaining the method you used. That checks understanding.', 9, false);
insert into public.posts (id, legacy_id, community_slug, title, type, content, author_username, upvotes, solved, tags) values ('65ea1c69-d243-0fc9-42f5-87c1e71a7a60', '1', 'veterinary_medicine', 'What should be in a basic pet first-aid kit?', 'question', 'I want to keep supplies at home for small issues and emergencies while knowing when to call the vet.', 'sarah', 36, true, array['first aid','pet care','emergency']::text[]);
insert into public.comments (id, legacy_id, post_id, author_username, content, upvotes, accepted) values ('a9be185b-0f85-2f96-6314-aeb646c5ba74', '1', '65ea1c69-d243-0fc9-42f5-87c1e71a7a60', 'elise', 'Include gauze, non-stick pads, vet wrap, saline rinse, digital thermometer, tweezers, and your clinic''s emergency number.', 22, true);
insert into public.comment_replies (id, legacy_id, comment_id, author_username, content) values ('7587ebfb-bb65-c5d3-8342-f7bbf31a312c', '101', 'a9be185b-0f85-2f96-6314-aeb646c5ba74', 'sarah', 'Adding the emergency number to the box is smart.');
insert into public.comments (id, legacy_id, post_id, author_username, content, upvotes, accepted) values ('3b9e9fa1-f5a1-9303-7700-5f3c0b5e3a8a', '2', '65ea1c69-d243-0fc9-42f5-87c1e71a7a60', 'maya', 'Do not include human pain medicine unless your vet specifically instructs it. Many are unsafe for pets.', 20, false);
insert into public.comments (id, legacy_id, post_id, author_username, content, upvotes, accepted) values ('ee751ea7-42be-899e-5077-aadd4d3dedfc', '3', '65ea1c69-d243-0fc9-42f5-87c1e71a7a60', 'noah', 'A muzzle or soft wrap can help during transport, but never use one if the animal is vomiting or struggling to breathe.', 16, false);
insert into public.comment_replies (id, legacy_id, comment_id, author_username, content) values ('d9f13088-a514-6573-3fef-7cc755941228', '301', 'ee751ea7-42be-899e-5077-aadd4d3dedfc', 'elise', 'Good caveat. Safety depends on the situation.');
insert into public.comments (id, legacy_id, post_id, author_username, content, upvotes, accepted) values ('98c399e1-b325-563a-849d-0bfcb14190e7', '4', '65ea1c69-d243-0fc9-42f5-87c1e71a7a60', 'lucas', 'Keep a copy of vaccine records and current medications in a small waterproof pouch.', 13, false);
insert into public.comments (id, legacy_id, post_id, author_username, content, upvotes, accepted) values ('13874a05-c80c-ee34-00e2-a90949569b85', '5', '65ea1c69-d243-0fc9-42f5-87c1e71a7a60', 'anna', 'Check expiration dates twice a year. Saline and ointments quietly expire in the back of a cabinet.', 9, false);
insert into public.comment_replies (id, legacy_id, comment_id, author_username, content) values ('4b735df6-9f02-4cdb-2dbb-6bf512d7b9ee', '501', '13874a05-c80c-ee34-00e2-a90949569b85', 'sarah', 'I will put that on my calendar.');
insert into public.comments (id, legacy_id, post_id, author_username, content, upvotes, accepted) values ('34c19059-9e81-db88-3589-4a2a15da8b88', '6', '65ea1c69-d243-0fc9-42f5-87c1e71a7a60', 'diego', 'If you hike, add a tick remover and booties for paw injuries.', 8, false);
insert into public.comments (id, legacy_id, post_id, author_username, content, upvotes, accepted) values ('fa1ce5f3-7fcb-a90e-2692-111b7fff5770', '7', '65ea1c69-d243-0fc9-42f5-87c1e71a7a60', 'camille', 'Label the kit clearly so a pet sitter can find it fast.', 7, false);
insert into public.posts (id, legacy_id, community_slug, title, type, content, author_username, upvotes, solved, tags) values ('47504ce6-8505-4d9c-0ddb-8c49f2ea0f11', '2', 'veterinary_medicine', 'How do vet students practice communicating bad news?', 'discussion', 'The medical knowledge is hard, but client conversations seem emotionally harder. How do students train for that?', 'pablo', 23, false, array['vet school','communication','clients']::text[]);
insert into public.comments (id, legacy_id, post_id, author_username, content, upvotes, accepted) values ('e8e835ec-f552-f318-ab7e-a5f0c0272467', '1', '47504ce6-8505-4d9c-0ddb-8c49f2ea0f11', 'elise', 'Many programs use simulated clients. Students practice with actors and get feedback on clarity and empathy.', 14, false);
insert into public.comment_replies (id, legacy_id, comment_id, author_username, content) values ('6d2bea9c-4012-b01c-6c5b-e83497b6dbd2', '101', 'e8e835ec-f552-f318-ab7e-a5f0c0272467', 'pablo', 'I did not know actors were part of training.');
insert into public.comments (id, legacy_id, post_id, author_username, content, upvotes, accepted) values ('4978fa41-3e1c-12ae-0565-0b89ab8fbdee', '2', '47504ce6-8505-4d9c-0ddb-8c49f2ea0f11', 'maya', 'A useful structure is warning shot, clear statement, pause, then options. Do not fill every silence.', 16, false);
insert into public.comments (id, legacy_id, post_id, author_username, content, upvotes, accepted) values ('681f7ce8-aaf8-f827-a1ca-4ba17be1a81b', '3', '47504ce6-8505-4d9c-0ddb-8c49f2ea0f11', 'anna', 'Shadowing experienced clinicians helps because you see how they balance honesty with gentleness.', 10, false);
insert into public.comments (id, legacy_id, post_id, author_username, content, upvotes, accepted) values ('266006a6-be8d-4ead-583c-eb397b0f4cdf', '4', '47504ce6-8505-4d9c-0ddb-8c49f2ea0f11', 'diego', 'Students also learn to avoid jargon. Owners need understandable next steps, not a lecture.', 11, false);
insert into public.comment_replies (id, legacy_id, comment_id, author_username, content) values ('b7fc7e5f-e5b7-cdb0-7cee-21959afa470c', '401', '266006a6-be8d-4ead-583c-eb397b0f4cdf', 'sarah', 'That is true in human medicine too.');
insert into public.comments (id, legacy_id, post_id, author_username, content, upvotes, accepted) values ('0ac25dde-2651-6630-9b81-c4c2ecd8faee', '5', '47504ce6-8505-4d9c-0ddb-8c49f2ea0f11', 'camille', 'Debriefing matters. Those conversations can stay with you, so programs teach peer support too.', 9, false);
insert into public.posts (id, legacy_id, community_slug, title, type, content, author_username, upvotes, solved, tags) values ('6e8af6bc-3598-de62-c641-240abac0c80e', '1', 'medicine', 'How do you remember the difference between sensitivity and specificity?', 'question', 'I keep reversing these in practice questions. Any memory trick that still preserves the real meaning?', 'noah', 40, true, array['diagnostics','statistics','study tips']::text[]);
insert into public.comments (id, legacy_id, post_id, author_username, content, upvotes, accepted) values ('b321ac44-38ac-60f2-0f40-13fe1b5ee856', '1', '6e8af6bc-3598-de62-c641-240abac0c80e', 'maya', 'Sensitivity asks: among people with the disease, how many test positive? Specificity asks: among people without it, how many test negative?', 25, true);
insert into public.comment_replies (id, legacy_id, comment_id, author_username, content) values ('3d305edb-407e-7db3-e9cd-e71a38861af4', '101', 'b321ac44-38ac-60f2-0f40-13fe1b5ee856', 'noah', 'Starting with the group first makes this clearer.');
insert into public.comments (id, legacy_id, post_id, author_username, content, upvotes, accepted) values ('7c97f74a-bb17-645a-4bad-a941f8f0264a', '2', '6e8af6bc-3598-de62-c641-240abac0c80e', 'lucas', 'SnNout and SpPin are useful, but only after you understand the denominators.', 18, false);
insert into public.comments (id, legacy_id, post_id, author_username, content, upvotes, accepted) values ('14fa3221-5eb7-82c3-f840-3beaebf6d0be', '3', '6e8af6bc-3598-de62-c641-240abac0c80e', 'anna', 'Draw a two-by-two table every time until it becomes automatic.', 13, false);
insert into public.comment_replies (id, legacy_id, comment_id, author_username, content) values ('446b496c-4bec-a43b-3494-e0c8b35c5229', '301', '14fa3221-5eb7-82c3-f840-3beaebf6d0be', 'pablo', 'The table stops me from guessing.');
insert into public.comments (id, legacy_id, post_id, author_username, content, upvotes, accepted) values ('895daa0e-e59a-bf36-9667-4a693d549dad', '4', '6e8af6bc-3598-de62-c641-240abac0c80e', 'elise', 'High sensitivity is good for screening because you miss fewer true cases.', 12, false);
insert into public.comments (id, legacy_id, post_id, author_username, content, upvotes, accepted) values ('ab28c18e-77f7-fe45-d1de-4c8cfde4917b', '5', '6e8af6bc-3598-de62-c641-240abac0c80e', 'diego', 'High specificity is useful for confirming because positives are less likely to be false positives.', 10, false);
insert into public.comment_replies (id, legacy_id, comment_id, author_username, content) values ('ad8e7e56-d473-1b2d-66a0-5b6d02f39374', '501', 'ab28c18e-77f7-fe45-d1de-4c8cfde4917b', 'noah', 'Screening versus confirming is a good anchor.');
insert into public.comments (id, legacy_id, post_id, author_username, content, upvotes, accepted) values ('9964d9af-cf15-8597-ddb9-38d9e1838407', '6', '6e8af6bc-3598-de62-c641-240abac0c80e', 'camille', 'Practice with fake numbers like 100 sick and 100 well. Percentages become less abstract.', 8, false);
insert into public.posts (id, legacy_id, community_slug, title, type, content, author_username, upvotes, solved, tags) values ('c6022316-25b9-8c46-5bd0-658ae4857d5f', '2', 'medicine', 'Managing study burnout during pre-clinicals', 'discussion', 'I can keep up for a few weeks, then I crash and lose momentum. What habits helped you stay steady?', 'anna', 29, false, array['burnout','medical school','wellbeing']::text[]);
insert into public.comments (id, legacy_id, post_id, author_username, content, upvotes, accepted) values ('ca9bf650-1f52-a065-f17a-3f7f411f56b8', '1', 'c6022316-25b9-8c46-5bd0-658ae4857d5f', 'sarah', 'Protect sleep first. Every other study system collapses when sleep debt gets too large.', 17, false);
insert into public.comments (id, legacy_id, post_id, author_username, content, upvotes, accepted) values ('aa9a8a8d-2261-ad2c-cf15-20acd1aba28d', '2', 'c6022316-25b9-8c46-5bd0-658ae4857d5f', 'maya', 'Use a minimum viable study day for bad days: one review block, one question set, then stop without guilt.', 19, false);
insert into public.comment_replies (id, legacy_id, comment_id, author_username, content) values ('e3f44a70-3a03-da77-0bbd-0101c0140457', '201', 'aa9a8a8d-2261-ad2c-cf15-20acd1aba28d', 'anna', 'I like having a version of success for low-energy days.');
insert into public.comments (id, legacy_id, post_id, author_username, content, upvotes, accepted) values ('ce6cb77e-d9ff-7111-262a-bf862ca1d32e', '3', 'c6022316-25b9-8c46-5bd0-658ae4857d5f', 'noah', 'Schedule one non-medical thing every week. It sounds small, but it keeps your identity wider than exams.', 14, false);
insert into public.comment_replies (id, legacy_id, comment_id, author_username, content) values ('4ae3be3e-406d-f13c-3db1-c821abeba904', '301', 'ce6cb77e-d9ff-7111-262a-bf862ca1d32e', 'lucas', 'This made a big difference for my cohort.');
insert into public.posts (id, legacy_id, community_slug, title, type, content, author_username, upvotes, solved, tags) values ('d6f44c1d-6f95-ecbe-bbff-0c97b8738ea4', '1', 'philosophy', 'Can utilitarianism protect individual rights?', 'question', 'If the goal is maximizing overall happiness, what stops a majority from sacrificing one person unfairly?', 'lucas', 32, true, array['ethics','utilitarianism','rights']::text[]);
insert into public.comments (id, legacy_id, post_id, author_username, content, upvotes, accepted) values ('ce474537-f084-bec0-89c2-329adfc7dd30', '1', 'd6f44c1d-6f95-ecbe-bbff-0c97b8738ea4', 'camille', 'Rule utilitarians argue that rights-protecting rules create better outcomes over time than case-by-case exceptions.', 21, true);
insert into public.comment_replies (id, legacy_id, comment_id, author_username, content) values ('c43df24b-d979-f578-c2a6-eb2dc6c8f2a9', '101', 'ce474537-f084-bec0-89c2-329adfc7dd30', 'lucas', 'So the protection comes from adopting stable rules?');
insert into public.comment_replies (id, legacy_id, comment_id, author_username, content) values ('64120f95-c3dc-e534-d660-eb18644b1455', '102', 'ce474537-f084-bec0-89c2-329adfc7dd30', 'camille', 'Yes. Trust and security are part of the utility calculation.');
insert into public.comments (id, legacy_id, post_id, author_username, content, upvotes, accepted) values ('b9e5e7d2-72ed-ac4b-06ce-a200d9030567', '2', 'd6f44c1d-6f95-ecbe-bbff-0c97b8738ea4', 'anna', 'Critics would say this still makes rights contingent, which is why deontologists object.', 18, false);
insert into public.comments (id, legacy_id, post_id, author_username, content, upvotes, accepted) values ('9004fda0-95ba-5283-7189-259846385573', '3', 'd6f44c1d-6f95-ecbe-bbff-0c97b8738ea4', 'pablo', 'Mill tries to defend liberty partly by arguing that individuality and free discussion benefit society.', 14, false);
insert into public.comment_replies (id, legacy_id, comment_id, author_username, content) values ('fafa6c4b-851e-4a7c-feb8-d9905e94d866', '301', '9004fda0-95ba-5283-7189-259846385573', 'noah', 'Mill is a good bridge between rights language and utility language.');
insert into public.comments (id, legacy_id, post_id, author_username, content, upvotes, accepted) values ('8f7d46eb-8ffa-5b3e-297c-424b300fd937', '4', 'd6f44c1d-6f95-ecbe-bbff-0c97b8738ea4', 'sarah', 'The hard cases are where violating one person''s rights seems to produce a huge immediate benefit.', 11, false);
insert into public.comments (id, legacy_id, post_id, author_username, content, upvotes, accepted) values ('e084bc57-ab80-1243-332f-ded64d39d176', '5', 'd6f44c1d-6f95-ecbe-bbff-0c97b8738ea4', 'maya', 'Some utilitarians include preference satisfaction, not just pleasure, which changes the analysis.', 9, false);
insert into public.comments (id, legacy_id, post_id, author_username, content, upvotes, accepted) values ('017b50c2-49fe-ee62-6408-eea0ced1c5fb', '6', 'd6f44c1d-6f95-ecbe-bbff-0c97b8738ea4', 'diego', 'This is why thought experiments like the transplant case are so common in ethics classes.', 8, false);
insert into public.comment_replies (id, legacy_id, comment_id, author_username, content) values ('2b71a571-7cf1-0dd9-aa73-21bd4cb7f5f9', '601', '017b50c2-49fe-ee62-6408-eea0ced1c5fb', 'lucas', 'That example is exactly what made me ask.');
insert into public.comments (id, legacy_id, post_id, author_username, content, upvotes, accepted) values ('c2fd94a5-50f8-b1c7-4aa2-8789146a8125', '7', 'd6f44c1d-6f95-ecbe-bbff-0c97b8738ea4', 'elise', 'A utilitarian can protect rights strongly, but usually not absolutely.', 12, false);
insert into public.comments (id, legacy_id, post_id, author_username, content, upvotes, accepted) values ('3009d6e5-2dfe-79ec-1b66-52b320199d03', '8', 'd6f44c1d-6f95-ecbe-bbff-0c97b8738ea4', 'omar', 'Compare act utilitarianism, rule utilitarianism, and Kantian ethics side by side. The contrast is useful.', 10, false);
insert into public.posts (id, legacy_id, community_slug, title, type, content, author_username, upvotes, solved, tags) values ('10df3ac4-f65e-b662-8e42-a6253d65547e', '2', 'philosophy', 'Where should a beginner start with existentialism?', 'discussion', 'I want something readable before jumping into dense primary texts. What order would you recommend?', 'sarah', 26, false, array['existentialism','reading list','beginners']::text[]);
insert into public.comments (id, legacy_id, post_id, author_username, content, upvotes, accepted) values ('c9d28aed-5013-d817-ed95-ebcc501a03a6', '1', '10df3ac4-f65e-b662-8e42-a6253d65547e', 'camille', 'Start with Camus essays or The Stranger, then read Sartre''s Existentialism Is a Humanism.', 15, false);
insert into public.comment_replies (id, legacy_id, comment_id, author_username, content) values ('c9360346-a13d-8a31-e684-08501686a157', '101', 'c9d28aed-5013-d817-ed95-ebcc501a03a6', 'sarah', 'That sounds approachable.');
insert into public.comments (id, legacy_id, post_id, author_username, content, upvotes, accepted) values ('f9c13598-5aed-fe99-4396-7433c3192cc6', '2', '10df3ac4-f65e-b662-8e42-a6253d65547e', 'noah', 'Kierkegaard is important, but he is easier after you know the broad questions.', 11, false);
insert into public.comments (id, legacy_id, post_id, author_username, content, upvotes, accepted) values ('90f8e284-0699-a566-4ff3-d48abed39f98', '3', '10df3ac4-f65e-b662-8e42-a6253d65547e', 'anna', 'Read short secondary introductions alongside primary texts. Context prevents a lot of confusion.', 13, false);
insert into public.comment_replies (id, legacy_id, comment_id, author_username, content) values ('ed7c941b-708a-c7ac-7ccd-fdcfc5387d9b', '301', '90f8e284-0699-a566-4ff3-d48abed39f98', 'lucas', 'A glossary also helps because terms shift between authors.');
insert into public.comments (id, legacy_id, post_id, author_username, content, upvotes, accepted) values ('59e70ed1-fe1e-fb9a-5feb-35358a8bc64d', '4', '10df3ac4-f65e-b662-8e42-a6253d65547e', 'pablo', 'Do not skip Simone de Beauvoir. The Ethics of Ambiguity connects existentialism to lived choices.', 14, false);
